// Bundled sample photos for the QA debug affordance (v0.8.25).
// Tiny flat-illustration PNGs (160x160, quantized) so the photo-dependent
// scan stages can be exercised by automation without the native file
// chooser or camera permission. They are decoded from base64 constants
// instead of being registered as assets, so the pubspec asset list stays
// untouched.
import 'dart:convert';
import 'dart:typed_data';

const String _kSamplePhoto1B64 =
    '';
const String _kSamplePhoto2B64 =
    '';

/// Decodes the bundled sample photos. Order matters: photo 1 is the
/// tabletop scene, photo 2 the bedside table.
List<Uint8List> loadSamplePhotoBytes() => <Uint8List>[
      base64Decode(_kSamplePhoto1B64),
      base64Decode(_kSamplePhoto2B64),
    ];
